import * as Logger from '../UNSAFE_logger';

const ALLOWED_PROTOCOL_LIST = ['http:', 'https:', 'mailto:', 'tel:', 'sms:'];
const ALLOWED_PROTOCOLS = new Set(ALLOWED_PROTOCOL_LIST);
const ALLOWED_PROTOCOLS_MESSAGE = ALLOWED_PROTOCOL_LIST.join(', ');

/**
 * Returns a safe href for anchor elements, or undefined when the URL uses an
 * unsafe protocol such as javascript: or data:.
 */
export function getSafeHref(href?: string, componentName = 'JET Link'): string | undefined {
  if (href == null) {
    return undefined;
  }

  const trimmedHref = href.trim();
  try {
    const protocol = new URL(trimmedHref, 'http://localhost').protocol.toLowerCase();
    if (ALLOWED_PROTOCOLS.has(protocol)) {
      return trimmedHref;
    }
    Logger.warn(
      `${componentName}: href was blocked because protocol "${protocol}" is not allowed. ` +
        `Allowed protocols are ${ALLOWED_PROTOCOLS_MESSAGE}.`
    );
    return undefined;
  } catch {
    Logger.warn(
      `${componentName}: href was blocked because it could not be parsed. ` +
        `Allowed protocols are ${ALLOWED_PROTOCOLS_MESSAGE}.`
    );
    return undefined;
  }
}
